('notable_npc', 'struwwelpeter', 'Full Strength Claw Swipe', '3D6 M.D.', 1, NULL, NULL, 1),
('notable_npc', 'struwwelpeter', 'Power Claw Slash', '6D6 M.D.', 1, NULL, 'Takes two melee actions.', 2),
('notable_npc', 'struwwelpeter', 'Fingernail Scratch', '2D4 S.D.C.', 0, NULL, NULL, 3),
('notable_npc', 'struwwelpeter', 'Scissor Cut', '1D6x10 M.D.', 1, NULL, 'Takes two melee actions.', 4),
('notable_npc', 'struwwelpeter', 'Kick', '2D6 M.D.', 1, NULL, NULL, 5),
('notable_npc', 'struwwelpeter', 'Bite (dog form)', '4D6 S.D.C.', 0, NULL, '2D4 M.D. against Mega-Damage opponents; the victim must save vs disease or fall ill with fever for 1D6 days.', 6);

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 3 notable NPCs are in' AS assertion, count(*) AS got, 3 AS want
  FROM notable_npcs WHERE slug IN ('jinna-gir-song', 'struwwelpeter', 'general-rasheen');
SELECT 'and the notables 7' AS assertion, count(*) AS got, 7 AS want
  FROM stat_attacks WHERE owner_kind = 'notable_npc' AND owner_slug IN ('jinna-gir-song', 'struwwelpeter', 'general-rasheen');

